function fitGraph(){if(!scene?.nodes.length)return;const pts=scene.nodes.map(n=>positions.get(n.id));const left=Math.min(...pts.map(p=>p.x))-85,right=Math.max(...pts.map(p=>p.x))+85,top=Math.min(...pts.map(p=>p.y))-60,bottom=Math.max(...pts.map(p=>p.y))+65;zoom=Math.min(1.3,900/Math.max(1,right-left),390/Math.max(1,bottom-top));pan={x:500-(left+right)/2*zoom,y:275-(top+bottom)/2*zoom};}
function graphEdgePath(edge){const a=positions.get(edge.from),b=positions.get(edge.to),k=edge.groupSize||1,i=edge.groupIndex||0,labelHeight=connectionLabelLines(edge).length*14+10;
 if(edge.from===edge.to){const h=90+i*Math.min(labelHeight+6,40);return {path:`M ${a.x-14} ${a.y-16} C ${a.x-80-i*12} ${a.y-h},${a.x+80+i*12} ${a.y-h},${a.x+17} ${a.y-14}`,x:a.x,y:a.y-h*.75+8,step:labelHeight+6,labelHeight};}
 // Offsets are measured in the pair's own frame so opposite directions share one fan without crossing.
 const [p,q]=edge.from<edge.to?[a,b]:[b,a],len=Math.hypot(q.x-p.x,q.y-p.y)||1,nx=-(q.y-p.y)/len,ny=(q.x-p.x)/len;
 const step=k>1?Math.min(labelHeight+6,420/(k-1)):0,offset=(i-(k-1)/2)*step,mx=(a.x+b.x)/2,my=(a.y+b.y)/2,cx=mx+nx*offset*2,cy=my+ny*offset*2;
 const unit=(x,y)=>{const l=Math.hypot(x,y)||1;return [x/l,y/l];},[sx,sy]=unit(cx-a.x,cy-a.y),[ex,ey]=unit(b.x-cx,b.y-cy);
 return {path:`M ${a.x+sx*25} ${a.y+sy*25} Q ${cx} ${cy} ${b.x-ex*27} ${b.y-ey*27}`,x:mx+nx*offset,y:my+ny*offset+labelHeight/2-5,step:k>1?step:Infinity,labelHeight};}
function connectionLabelLines(edge,showDates=state.graphDates===true){
 const lines=Object.entries(edge.totals).sort(([a],[b])=>a.localeCompare(b)).map(([asset,value])=>(edge.n>1?'Σ ':'')+amount(value)+' '+asset);
 if(edge.n>1)lines.push(edge.n+' movimentos · totais por ativo');
 if(showDates){const times=edge.events.map(e=>e.time).filter(Number.isFinite);if(times.length){const first=Math.min(...times),last=Math.max(...times);if(first===last)lines.push(date(first));else{lines.push('De '+date(first));lines.push('Até '+date(last));}}}
 return lines;
}
function connectionLabelSVG(edge,g){const lines=connectionLabelLines(edge),height=lines.length*14+10,width=Math.max(110,...lines.map(l=>l.length*6.2+14));const y=g.y-height+5;return `<rect x="${g.x-width/2}" y="${y}" width="${width}" height="${height}" rx="4" fill="#1b1d1e" fill-opacity=".94" stroke="#454947" stroke-width=".6"/><text x="${g.x}" y="${y+15}" fill="#b9cae1" font-size="10" text-anchor="middle">${lines.map((line,i)=>`<tspan x="${g.x}" dy="${i?14:0}">${esc(line)}</tspan>`).join('')}</text>`;}
function renderGraph(){
 const first=!scene?.nodes.length;const events=Object.values(state.events).filter(e=>onGraph(e.id)&&(!$('#asset').value||e.asset===$('#asset').value));
 const hidden=graphHiddenAddressSet();scene=buildGraphScene(events,state.addresses.filter(a=>!hidden.has(a.address)));placeGraphNodes(scene.nodes);const hiddenCount=graphHiddenCount();$('#restoreHidden').hidden=!hiddenCount;$('#restoreHidden').textContent='↺ Restaurar nós ('+hiddenCount+')';if(first)fitGraph();
 const selectedCount=scene.nodes.filter(n=>selectedNodes.has(n.id)).length;for(const id of ['alignH','alignV','distributeH','distributeV'])$('#'+id).disabled=selectedCount<2;$('#nodeSelectionCount').textContent=selectedNodes.size?selectedNodes.size+' nós selecionados':'';$('#empty').hidden=!!state.addresses.length;$('.graph-panel').classList.toggle('is-empty',!state.addresses.length);$('#graphDates').textContent=state.graphDates?'Ocultar data e hora':'Mostrar data e hora';$('#graphDates').setAttribute('aria-pressed',String(state.graphDates===true));$('#zoomLabel').textContent=Math.round(zoom*100)+'%';
 $('#graph').innerHTML=`<defs><marker id="flowArrow" markerWidth="10" markerHeight="8" refX="9" refY="4" orient="auto" markerUnits="userSpaceOnUse"><path d="M 0 0 L 10 4 L 0 8 Z" fill="context-stroke"/></marker></defs><g id="viewport" transform="translate(${pan.x},${pan.y}) scale(${zoom})">`+
 scene.edges.map(e=>{const g=graphEdgePath(e),selected=e.id===selection?.value;const color=selected?'#6a8fbf':e.assets.has('USDT')?'#5882b8':'#d7ae74',crowded=g.step<g.labelHeight,from=scene.nodes.find(n=>n.id===e.from).address,to=scene.nodes.find(n=>n.id===e.to).address;return {selected,svg:`<g class="edge${selected?' selected':''}" data-edge="${e.id}" tabindex="0" role="button" aria-label="${esc(connectionLabelLines(e,true).join(', '))} de ${from} para ${to}"><title>${esc(connectionLabelLines(e,true).join(' · '))}</title><path d="${g.path}" fill="none" stroke="transparent" stroke-width="${e.groupSize>1?Math.max(6,Math.min(18,g.step)):18}"/><path d="${g.path}" fill="none" stroke="${color}" stroke-width="${selected?3:1.8}" marker-end="url(#flowArrow)"/>${crowded&&!selected?'':connectionLabelSVG(e,g)}</g>`};}).sort((a,b)=>a.selected-b.selected).map(e=>e.svg).join('')+customArrowsSVG()+
 scene.nodes.map(n=>{const p=positions.get(n.id),monitored=n.lane===0,selected=selection?.value===n.address;return `<g class="node" data-node="${n.address}" data-visual="${n.id}" transform="translate(${p.x},${p.y})" tabindex="0" role="button" aria-label="${esc(nodeLabel(n.address)||n.address)}. Arraste para organizar ou use as setas do teclado; Enter para inspecionar; Shift+F10 abre o menu; Delete remove do gráfico.">${selectedNodes.has(n.id)?`<circle class="node-selected-ring" r="${monitored?28:23}"/>`:""}${nodeShapeSVG(n,monitored,selected)}<text text-anchor="middle" y="4" fill="${monitored?'white':'#9ea3a4'}" font-size="12">${monitored?'◎':'↔'}</text><rect x="-66" y="27" width="132" height="${n.repeated?32:18}" rx="4" fill="#1d1f20eb"/><text text-anchor="middle" y="39" font-size="10" fill="#c8cbcc">${esc((nodeLabel(n.address)||short(n.address)).slice(0,24))}</text>${n.repeated?'<text text-anchor="middle" y="53" font-size="8" fill="#939593">Também no outro lado</text>':''}<title>${esc(nodeLabel(n.address))}${nodeLabel(n.address)?" — ":""}${n.address}${n.repeated?' — mesmo endereço em entradas e saídas':''}</title></g>`;}).join('')+commentNotesSVG()+
 `<polygon id="selectionRegion" class="selection-region" points=""/></g>${state.addresses.length&&!events.length?`<text x="500" y="470" text-anchor="middle" font-size="12" fill="#9ea3a4">${Object.keys(state.events).length?Object.keys(state.events).length.toLocaleString('pt-BR')+' transações coletadas · marque no explorador as que devem aparecer no gráfico':'Nenhuma transação coletada ainda'}</text>`:''}<text x="980" y="505" text-anchor="end" font-size="10" fill="#6e7375">${new Set(scene.nodes.map(n=>n.address)).size} endereços${scene.omitted?' · limite visual de 100':''} · arraste os nós ou o fundo</text>`;
 $$('[data-node]').forEach(n=>{n.onclick=()=>showNode(n.dataset.node);n.onkeydown=e=>{if(e.key==='Enter')return n.click();const delta={ArrowLeft:[-12,0],ArrowRight:[12,0],ArrowUp:[0,-12],ArrowDown:[0,12]}[e.key];if(delta){e.preventDefault();const p=positions.get(n.dataset.visual);p.x+=delta[0];p.y+=delta[1];persistGraphPositions();renderGraph();$$('[data-visual]').find(v=>v.dataset.visual===n.dataset.visual)?.focus();}};});
 $$('[data-edge]').forEach(n=>{n.onclick=()=>showConnection(n.dataset.edge);n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();n.click();}};});
}
function persistGraphPositions(){state.graphPositions=Object.fromEntries(positions);save().catch(()=>{});}
// Convert CSS pixels through the SVG matrix: this includes letterboxing and zoom.
function graphPoint(e){const svg=$('#graph'),matrix=svg.getScreenCTM();if(!matrix)return null;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(matrix.inverse());}
$('#graph').addEventListener('click',e=>{if(suppressGraphClick){e.preventDefault();e.stopImmediatePropagation();suppressGraphClick=false;}},true);
$('#graph').addEventListener('wheel',e=>{e.preventDefault();if(drag)return;const p=graphPoint(e);if(!p)return;const previous=zoom;zoom=Math.max(.12,Math.min(4,zoom*(e.deltaY<0?1.1:.9)));pan={x:p.x-(p.x-pan.x)*zoom/previous,y:p.y-(p.y-pan.y)*zoom/previous};renderGraph();},{passive:false});
function pointInPolygon(p,polygon){let inside=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){const a=polygon[i],b=polygon[j],cross=(p.x-a.x)*(b.y-a.y)-(p.y-a.y)*(b.x-a.x);if(Math.abs(cross)<1e-7&&p.x>=Math.min(a.x,b.x)&&p.x<=Math.max(a.x,b.x)&&p.y>=Math.min(a.y,b.y)&&p.y<=Math.max(a.y,b.y))return true;if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside;}
function selectionRectangle(points){const a=points[0],b=points[points.length-1];return [a,{x:b.x,y:a.y},b,{x:a.x,y:b.y}];}
function alignSelectedNodes(orientation,distribute=false){
 const nodes=(scene?.nodes||[]).filter(n=>selectedNodes.has(n.id)&&positions.has(n.id));
 if(nodes.length<2){toast('Selecione pelo menos dois nós com Shift + arraste.');return false;}
 const along=orientation==='horizontal'?'x':'y',across=orientation==='horizontal'?'y':'x';
 const ordered=nodes.map(n=>({id:n.id,...positions.get(n.id)})).sort((a,b)=>a[along]-b[along]||a.id.localeCompare(b.id));
 const center=ordered.reduce((sum,p)=>sum+p[across],0)/ordered.length;
 let first=ordered[0][along],last=ordered[ordered.length-1][along];
 if(distribute&&last-first<1){const middle=(first+last)/2;first=middle-45*(ordered.length-1);last=middle+45*(ordered.length-1);}
 for(let i=0;i<ordered.length;i++){const p=ordered[i];positions.set(p.id,{x:p.x,y:p.y,[across]:center,...(distribute?{[along]:first+(last-first)*i/(ordered.length-1)}:{})});}
 persistGraphPositions();renderGraph();return true;
}
function handleGraphAlignmentKey(e){
 if(!e.shiftKey||e.altKey||e.repeat||drag||$('#monitor').hidden||document.querySelector('dialog[open]')||e.target?.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]'))return false;
 const key=String(e.key||'').toLowerCase();if(key!=='h'&&key!=='v')return false;
 e.preventDefault();e.stopPropagation();alignSelectedNodes(key==='h'?'horizontal':'vertical',e.ctrlKey||e.metaKey);return true;
}
$('#alignH').onclick=()=>alignSelectedNodes('horizontal');$('#alignV').onclick=()=>alignSelectedNodes('vertical');$('#distributeH').onclick=()=>alignSelectedNodes('horizontal',true);$('#distributeV').onclick=()=>alignSelectedNodes('vertical',true);document.addEventListener('keydown',handleGraphAlignmentKey,true);

function showGroupSelection(){const nodes=(scene?.nodes||[]).filter(n=>selectedNodes.has(n.id)),addresses=[...new Set(nodes.map(n=>n.address))];selection=addresses.length?{type:'nodes',addresses}:null;renderRows();renderGraph();$('#detail').innerHTML=`<span class="eyebrow">SELEÇÃO DE NÓS</span><h3>${nodes.length} nós · ${addresses.length} endereços</h3><p>Arraste um nó selecionado para mover o grupo. Shift+H/V alinha; Ctrl+Shift+H/V alinha e distribui. O explorador mostra os movimentos envolvendo estes endereços.</p>${addresses.map(a=>`<button class="group-node-button" data-group-address="${a}">${esc(nodeLabel(a)||short(a))}</button>`).join('')}`;$$('[data-group-address]').forEach(b=>b.onclick=()=>showNode(b.dataset.groupAddress));}
function clearNodeSelection(){selectedNodes.clear();const inspectingNodes=selection?.type==='nodes'||selection?.type==='node';if(inspectingNodes)selection=null;renderRows();renderGraph();if(inspectingNodes)$('#detail').innerHTML='<div class="detail-empty">↖<h3>Explore uma conexão</h3><p>Selecione um endereço ou uma transação para consultar os detalhes.</p></div>';}
function toggleGraphFullPage(on=!graphFullPage){graphFullPage=on;document.body.classList.toggle('graph-expanded',on);$('#fullGraph').textContent=on?'↙ Voltar ao painel':'⛶ Página inteira';$('#fullGraph').setAttribute('aria-pressed',String(on));}
$('#fullGraph').onclick=()=>toggleGraphFullPage();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){if(graphFullPage)toggleGraphFullPage(false);else if(selectedNodes.size)clearNodeSelection();else if(selection?.type==='event'){selection=null;renderRows();renderGraph();}else if(workspaceUI.inspectorOpen)setInspectorOpen(false);}});
$('#graph').onpointerdown=e=>{if(e.button!==0||drag)return;suppressGraphClick=false;const target=e.target.closest('[data-visual]');if(!e.shiftKey&&!target&&e.target.closest('[data-edge],[data-arrow]'))return;const p=graphPoint(e);if(!p)return;e.preventDefault?.();if(e.shiftKey){drag={mode:'rectangle',pointerId:e.pointerId,id:target?.dataset.visual,start:p,points:[{x:(p.x-pan.x)/zoom,y:(p.y-pan.y)/zoom}],client:{x:e.clientX,y:e.clientY},moved:false};}else{const id=target?.dataset.visual,node=id?positions.get(id):null,ids=id&&selectedNodes.has(id)?[...selectedNodes]:id?[id]:[];drag={mode:id?'nodes':'pan',pointerId:e.pointerId,id,start:p,origin:node?{...node}:{...pan},origins:new Map(ids.filter(id=>positions.has(id)).map(id=>[id,{...positions.get(id)}])),zoom,moved:false,client:{x:e.clientX,y:e.clientY}};}$('#graph').setPointerCapture(e.pointerId);$('#graph').classList.add('dragging');};
$('#graph').onpointermove=e=>{if(!drag||e.pointerId!==drag.pointerId)return;const p=graphPoint(e);if(!p)return;if(!drag.moved&&Math.hypot(e.clientX-drag.client.x,e.clientY-drag.client.y)<4)return;drag.moved=true;if(drag.mode==='rectangle'){const world={x:(p.x-pan.x)/zoom,y:(p.y-pan.y)/zoom};drag.points=[drag.points[0],world];const poly=selectionRectangle(drag.points);$('#selectionRegion')?.setAttribute('points',poly.map(p=>p.x+','+p.y).join(' '));return;}const dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(drag.mode==='nodes'){for(const [id,origin]of drag.origins)positions.set(id,{x:origin.x+dx/drag.zoom,y:origin.y+dy/drag.zoom});renderGraph();}else{pan={x:drag.origin.x+dx,y:drag.origin.y+dy};$('#viewport')?.setAttribute('transform',`translate(${pan.x},${pan.y}) scale(${zoom})`);}};
function endGraphDrag(e){if(!drag||e.pointerId!==drag.pointerId)return;const finished=drag;drag=null;suppressGraphClick=finished.moved||!!finished.id;$('#graph').classList.remove('dragging');if(finished.mode==='rectangle'){suppressGraphClick=true;if(e.type==='pointercancel'){renderGraph();}else{if(finished.moved){const polygon=selectionRectangle(finished.points);for(const n of scene.nodes){const p=positions.get(n.id);if(pointInPolygon(p,polygon))selectedNodes.add(n.id);}}else if(finished.id){if(selectedNodes.has(finished.id))selectedNodes.delete(finished.id);else selectedNodes.add(finished.id);}showGroupSelection();}}else{if(finished.mode==='pan'&&!finished.moved&&e.type==='pointerup')clearNodeSelection();if(finished.id&&!finished.moved&&e.type==='pointerup'){const node=scene.nodes.find(n=>n.id===finished.id);if(node)showNode(node.address);}if(finished.id&&finished.moved)persistGraphPositions();}if($('#graph').hasPointerCapture(e.pointerId))$('#graph').releasePointerCapture(e.pointerId);}
