function connectionNavigation(context,id){if(!context?.eventIds?.length)return '';const events=context.eventIds.map(id=>state.events[id]).filter(Boolean);return `<div class="connection-navigation"><span class="eyebrow">CONEXÃO · ${events.length} MOVIMENTO${events.length>1?'S':''}</span>${events.length>1?`<label>Selecione o movimento<select id="connectionEvents" aria-label="Movimento desta conexão">${events.map(e=>`<option value="${esc(e.id)}" ${e.id===id?'selected':''}>${esc(date(e.time))} · ${amount(e.value)} ${e.asset} · ${short(e.hash)} #${e.index}</option>`).join('')}</select></label><p>Movimentos desta direção marcados no gráfico, do mais recente ao mais antigo. Cada um é uma seta própria.</p>`:''}</div>`;}
