 s.nodeComments=obj(s.nodeComments)?Object.fromEntries(Object.entries(s.nodeComments).filter(([a,v])=>TRON_ADDRESS.test(a)&&typeof v==='string'&&v.trim()).map(([a,v])=>[a,v.slice(0,500)])):{};
 s.commentPositions=obj(s.commentPositions)?Object.fromEntries(Object.entries(s.commentPositions).filter(([a,v])=>TRON_ADDRESS.test(a)&&obj(v)&&Number.isFinite(v.dx)&&Number.isFinite(v.dy)&&Math.abs(v.dx)<20000&&Math.abs(v.dy)<20000).map(([a,v])=>[a,{dx:v.dx,dy:v.dy}])):{};
