// A newly marked transaction brings its addresses back to the graph.
function unhideForEvents(ids){if(!graphHiddenCount())return;for(const id of ids){const e=state.events[id];if(e&&state.graphSelected?.[id]){delete state.graphHidden[e.from];delete state.graphHidden[e.to];}}}
function graphHiddenAddressSet(){const hidden=new Set(Object.keys(state.graphHidden||{}));if(hidden.size)for(const id of Object.keys(state.graphSelected||{})){const e=state.events[id];if(e){hidden.delete(e.from);hidden.delete(e.to);}}return hidden;}
