function monitorFromGraph(address){closeNodeMenu();const existing=state.addresses.find(a=>a.address===address);if(existing&&!existing.expanded)return toast('Este endereço já é monitorado.');openAddress();if(!$('#addressDialog').open)return;const form=$('#addressForm');form.elements.namedItem('address').value=address;form.elements.namedItem('label').value=nodeLabel(address);form.elements.namedItem('start').focus();}
