// Status notices can be closed; a notice comes back only when its text changes (new error or new pending set). Kept for this page load.
const dismissedCoverage=new Map();
function coverageNotices(){return state.addresses.map(a=>{const pending=['trx','usdt'].filter(k=>!a.streams?.[k]||a.streams[k].initial||a.streams[k].window);const text=a.error?`${a.label||short(a.address)} — ${a.error}. Dados anteriores preservados.`:pending.length?`${a.label||short(a.address)}: histórico em carregamento (${pending.join(', ').toUpperCase()}). Até 3 páginas por ativo em cada atualização; clique em Atualizar para continuar.`:'';return {address:a.address,error:!!a.error,text};}).filter(n=>n.text&&dismissedCoverage.get(n.address)!==n.text);}
function renderCoverage(){$('#coverage').innerHTML=coverageNotices().map(n=>`<div class="coverage${n.error?' error':''}"><span>${esc(n.text)}</span><button type="button" class="coverage-close" data-close-coverage="${n.address}" aria-label="Fechar aviso" title="Fechar aviso">×</button></div>`).join('');$$('[data-close-coverage]').forEach(b=>b.onclick=()=>{const n=coverageNotices().find(n=>n.address===b.dataset.closeCoverage);if(n)dismissedCoverage.set(n.address,n.text);renderCoverage();});}
// Comments are drawn as notes beside their node. The note keeps its offset from the node, so it follows the node and can be dragged on its own.
const NOTE_WIDTH=190;
function noteLines(text){const words=String(text).split(/\s+/).filter(Boolean),lines=[];let line='';for(const w of words){const next=line?line+' '+w:w;if(next.length>30&&line){lines.push(line);line=w;}else line=next;}if(line)lines.push(line);const out=lines.flatMap(l=>l.length>30?l.match(/.{1,30}/g):[l]);return out.length>8?[...out.slice(0,7),out[7].slice(0,28)+'…']:out;}
function noteOffset(address){const o=state.commentPositions?.[address];return o?{dx:o.dx,dy:o.dy}:{dx:-NOTE_WIDTH/2,dy:-120};}
function commentNotesSVG(){return Object.entries(state.nodeComments||{}).map(([address,text])=>{const id=arrowAnchor(address),p=id&&positions.get(id);if(!p)return '';const o=noteOffset(address),x=p.x+o.dx,y=p.y+o.dy,lines=noteLines(text),h=lines.length*13+26,cx=Math.max(x,Math.min(p.x,x+NOTE_WIDTH)),cy=Math.max(y,Math.min(p.y,y+h)),selected=selection?.type==='node'&&selection.value===address;
  return `<g class="comment-note${selected?' selected':''}" data-note="${address}" tabindex="0" role="button" aria-label="Comentário de ${esc(nodeLabel(address)||address)}: ${esc(text)}. Arraste para mover; Enter edita."><line x1="${p.x}" y1="${p.y}" x2="${cx}" y2="${cy}" stroke="#6f6a55" stroke-width="1" stroke-dasharray="3 3"/><rect x="${x}" y="${y}" width="${NOTE_WIDTH}" height="${h}" rx="5" fill="#26241c" stroke="${selected?'#7a9cc6':'#5e5844'}" stroke-width="${selected?1.6:1}"/><text x="${x+10}" y="${y+15}" font-size="8" letter-spacing="1" fill="#a8a07f">COMENTÁRIO · ${esc((nodeLabel(address)||short(address)).slice(0,14).toUpperCase())}</text><text x="${x+10}" y="${y+30}" font-size="10" fill="#e4dfcb">${lines.map((l,i)=>`<tspan x="${x+10}" dy="${i?13:0}">${esc(l)}</tspan>`).join('')}</text><title>${esc(text)}</title></g>`;}).join('');}
